param([ValidateSet("Release","Diagnostic")][string]$Profile="Release")
$ErrorActionPreference="Stop";$wslBuild="/tmp/phantom-ev3-$($Profile.ToLower())";$quotedSource="'"+(Resolve-Path ev3).Path+"'";$source=(wsl.exe -d Ubuntu -- wslpath -a $quotedSource).Trim();$diagnostic=if($Profile -eq "Diagnostic"){"ON"}else{"OFF"}
wsl.exe -d Ubuntu -- bash -lc "rm -rf '$wslBuild' && cmake -S '$source' -B '$wslBuild' -G Ninja -DCMAKE_BUILD_TYPE=Release -DPHANTOM_DIAGNOSTIC=$diagnostic && cmake --build '$wslBuild' && ctest --test-dir '$wslBuild' --output-on-failure"
if($LASTEXITCODE-ne 0){throw "EV3 host build failed"}
$out=Join-Path (Resolve-Path .) "build\ev3-host-$($Profile.ToLower())";New-Item -ItemType Directory -Force "$out\bin"|Out-Null
$configSource=if($Profile -eq "Diagnostic"){"config\generated\ev3-network-only.generated.json"}else{"config\generated\ev3.generated.json"};$bundleSource=if($Profile -eq "Diagnostic"){"config\generated\commissioning_bundle-network-only.generated.json"}else{"config\generated\commissioning_bundle.generated.json"}
$share="\\wsl.localhost\Ubuntu\tmp\phantom-ev3-$($Profile.ToLower())";Copy-Item "$share\phantom-controller","$share\phantom-safety" "$out\bin" -Force;Copy-Item deploy\scripts\device-auto.py "$out\bin\phantom-device-auto" -Force;Copy-Item deploy\scripts\wifi-autoconnect "$out\bin\phantom-wifi-autoconnect" -Force;Copy-Item ev3\network\phantom_network.py "$out\bin\phantom-network" -Force;Copy-Item ev3\network\phantom_mdns.py "$out\bin\phantom-mdns" -Force;Copy-Item protocol\phantom_protocol.py "$out\bin\phantom_protocol.py" -Force;Copy-Item protocol\wire_schema.yaml "$out\bin\wire_schema.yaml" -Force;Copy-Item $configSource "$out\config.generated.json" -Force;Copy-Item $bundleSource "$out\commissioning-bundle.generated.json" -Force;Copy-Item deploy\systemd "$out\systemd" -Recurse -Force;Copy-Item deploy\tmpfiles "$out\tmpfiles" -Recurse -Force
$bundleKey=if($Profile -eq "Diagnostic"){'commissioning_bundle-network-only'}else{'commissioning_bundle'};$bundleHash=(Get-Content config\generated\config-manifest.json -Raw|ConvertFrom-Json).artifact_hashes.$bundleKey
$commit=(git rev-parse HEAD).Trim();$dirty=((git status --porcelain).Count -gt 0);$manifest=[ordered]@{schema_version=1;build_id="$($commit.Substring(0,12))-$($Profile.ToLower())-host";git_commit=$commit;source_tree_hash=(python tools\source_hash.py ev3 protocol\generated).Trim();worktree_dirty=$dirty;build_profile=$Profile;target="host-test-not-armel";protocol_version=1;specification_sha256=(Get-FileHash docs\PHANTOM_SPECIFICATION.md -Algorithm SHA256).Hash.ToLower();protocol_schema_hash=(Get-Content protocol\generated\schema.sha256).Split()[0];compiler="g++ via WSL Ubuntu";config_hash=(Get-FileHash $configSource -Algorithm SHA256).Hash.ToLower();commissioning_bundle_hash=$bundleHash;build_time=(Get-Date).ToUniversalTime().ToString('o')};$manifest|ConvertTo-Json|Set-Content "$out\build-manifest.json" -Encoding UTF8
$checksumLines=Get-ChildItem $out -Recurse -File|Where-Object Name -ne SHA256SUMS|ForEach-Object{"$((Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower())  $($_.FullName.Substring($out.Length+1).Replace('\','/'))"}
[System.IO.File]::WriteAllText((Join-Path $out "SHA256SUMS"),(($checksumLines -join "`n")+"`n"),[System.Text.Encoding]::ASCII)
Write-Output "EV3 $Profile host artifact: $out"
